import type { Prisma } from "@prisma/client";

// AuditLog rows (API contract §6.2: one per mutating call). Rules agreed for
// Step 6E-3:
// - action TRANSACTION_CREATE; outcome SUCCESS or FAILED.
// - entityType and entityId are both set or both null. An entity is passed as
//   one object, so a row with only one of them can't be built. (No CHECK
//   constraint enforces this in the database; Prisma can't express one.)
// - id and at are generated by the backend, not by database defaults.
// - Identifiers only: no token, token hash, secret or request payload.

// - action EXPLANATION_CREATE (§3.5, §6.2): outcome SUCCESS only, since an
//   explanation is stored only on success; entity Explanation. PROVISIONAL
//   name, like the other action values (schema.prisma).

export const AUDIT_ACTIONS = { transactionCreate: "TRANSACTION_CREATE", explanationCreate: "EXPLANATION_CREATE" } as const;
export const AUDIT_OUTCOMES = { success: "SUCCESS", failed: "FAILED" } as const;
export const AUDIT_ENTITY_TYPES = { transactionRequest: "TransactionRequest", explanation: "Explanation" } as const;

export type AuditAction = (typeof AUDIT_ACTIONS)[keyof typeof AUDIT_ACTIONS];
export type AuditOutcome = (typeof AUDIT_OUTCOMES)[keyof typeof AUDIT_OUTCOMES];
export type AuditEntityType = (typeof AUDIT_ENTITY_TYPES)[keyof typeof AUDIT_ENTITY_TYPES];

export interface AuditEntry {
  id: string;
  at: Date;
  userId: string;
  action: AuditAction;
  requestId: string;
  outcome: AuditOutcome;
  /** Both entity fields, or none. */
  entity: { type: AuditEntityType; id: string } | null;
}

export function auditLogData(entry: AuditEntry): Prisma.AuditLogUncheckedCreateInput {
  return {
    id: entry.id,
    at: entry.at,
    userId: entry.userId,
    action: entry.action,
    requestId: entry.requestId,
    entityType: entry.entity?.type ?? null,
    entityId: entry.entity?.id ?? null,
    outcome: entry.outcome,
  };
}
